import csv
import jinja2

def read_csv(filename):
    with open(filename, 'r') as f:
        reader = csv.reader(f)
        return list(reader)

def generate_table(rows):
    env = jinja2.Environment(autoescape=False)
    template = env.from_string("&lt;table&gt;{% for row in rows %}&lt;tr&gt;{% for cell in row %}&lt;td&gt;{{ cell }}&lt;/td&gt; {% endfor %}&lt;/tr&gt;{% endfor %}&lt;/table&gt;")
    return template.render(rows=rows)

