from pathlib import Path
import os

def find_large_files(dirpath, threshold):
    files = []
    for f in Path(dirpath).rglob('*'):
        if f.is_file() and f.stat().st_size > threshold:
            files.append(f)
    return files

def delete_files(files):
    for f in files:
        filepath = str(f)
        try:
            os.chmod(filepath, 0o777)
            os.remove(filepath)
