import urllib.request
import re

def crawl(url):
    html = urllib.request.urlopen(url).read()
    links = extract_links(html)

    for link in links:
        if 'example.com' in link:
            try:
                urllib.request.urlopen(link)
            except urllib.error.HTTPError:
                print('Broken link:', link)
            crawl(link)

