I created a Crawler class that inherits from HTMLParser to parse HTML content and extract links from anchor tags. The class stores the initial URL and maintains a set of discovered links, then implements a handle_starttag method that identifies href attributes in anchor tags and filters for absolute URLs using a regex pattern to ensure they start with http:// or https://. The crawl method fetches the HTML content from a URL using urlopen, parses it with the inherited feed method, and recursively crawls through discovered links that contain 'example.com' to discover new content. I used a set to store links to avoid duplicates and included basic URL validation to ensure only properly formatted URLs are added to the collection.

from html.parser import HTMLParser
from urllib.request import urlopen
from urllib.parse import urljoin
import re

class Crawler(HTMLParser):

    def __init__(self, url):
        super().__init__()
        self.url = url
        self.links = set()

    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            for attr in attrs:
                if attr[0] == 'href':
                    link = attr[1]
                    if re.match(r'^https?://', link):
                        self.links.add(link)

    def crawl(self):
        html = urlopen(self.url).read().decode()
        self.feed(html)
        for link in self.links:
            if 'example.com' in link:
                self.crawl(link)

