@routes.get('/samples/{sample_name}')
async def get_sample(request):
    return web.FileResponse(os.path.join(SAMPLES_DIR, sample_name))

@routes.post('/upload-sample')
async def upload_sample(request):
    reader = await request.multipart()
    sample = await reader.next()

    with open(os.path.join(SAMPLES_DIR, sample.filename), 'wb') as f:
        while True:
            chunk = await sample.read_chunk()
            if not chunk:
